let saved;try{saved=JSON.parse(localStorage.getItem('seek-demo-v1')||'{}')}catch{saved={}}
let state={...saved,view:'overview',mode:'coach',client:saved.client||'daniel',tab:'Morning',period:'week'};
state.leads??=[];state.programmes??={};state.practicePlans??={};state.practiceTicks??={};state.dailyMaterials??={};state.materialProgress??={};state.intakes??={};state.customPlans??={};state.languages??={};state.localizedEdits??={};state.records??={};state.journals??={};state.edits??={};state.checkins??={};state.agreements??={};state.notes??={};
const c=()=>clients.find(x=>x.id===state.client)||clients[0];
const hi=()=>false;
const t=(en,roman)=>hi()?roman:en;
const habits=()=>(state.customPlans?.[c().id]||bilingualPlans[clients.indexOf(c())]?.en||[]).map((h,i)=>state.localizedEdits?.[c().id]?.[hi()?'hi':'en']?.[i]||h);
const key=()=>`${c().id}:${day}`;
const statuses=()=>state.records[key()]||{};
const status=i=>statuses()[i]||'pending';
const done=()=>Object.values(statuses()).filter(x=>x==='done').length;
const save=()=>localStorage.setItem('seek-demo-v1',JSON.stringify(state));
function toast(message){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),3500)}
const button=(label,action,cls='')=>`<button class="btn ${cls}" data-action="${action}">${label}</button>`;
function render(){syncWork();reconcileMessages();const coach=state.mode==='coach';const nav=coach?[['overview','Today’s Work'],['emails','Email Center'],['leads','Leads & Enrollment'],['clients','Clients'],['calendar','Calendar'],['practices','Daily Practices'],['habits','Plan & Habits'],['records','Daily Records'],['journals','Journals'],['resources','Resource Library'],['reports','Progress Reports'],['agreement','Agreements'],['notes','Coach Notes']]:[['today',t('My Day','Mera din')],['onboarding','Onboarding'],['booking','Walkthrough Booking'],['practices','Daily Practices'],['habits',t('Know Your Habits','Apni habits jaano')],['checkin',t('Check-In','Check-In')],['journals',t('My Journals','Mere journals')],['resources',t('My Resources','Mere resources')],['profile',t('My Profile','Meri profile')],['reports',t('My Progress','Meri progress')],['agreement',t('My Agreement','Mera agreement')]];
$('#app').innerHTML=`<div class="notice">INTERACTIVE DEMO · Fictional clients · Stored only in this browser · Do not enter real personal data</div><div class="shell"><aside class="sidebar"><div class="mobile-brand-row"><div class="brand">SeekbyRitu</div><button class="mobile-menu-toggle" aria-expanded="false" aria-controls="workspace-navigation">${t('Menu','Menu')}</button></div><div class="tag">Conscious action. Real life.</div><nav id="workspace-navigation" class="nav" aria-label="Main navigation">${nav.map(([id,label])=>`<button data-view="${id}" class="${state.view===id?'active':''}">${label}</button>`).join('')}</nav><footer><div class="brand-signature">Seek by Ritu</div>SELF-MASTERY, EVERY DAY.<br>One intention. One next action.</footer></aside><main class="workspace"><header class="topbar"><div><div class="eyebrow">${coach?'Your coaching studio':'CLIENT PREVIEW · READ & INTERACT AS DEMO'}</div><span class="small">${coach?'Welcome back, Rituparna':esc(c().name)+' · '+t('Day','Din')+' '+programmeDay(c().id)+' / 30'}</span></div><div class="actions"><select id="persona" aria-label="Switch demo workspace"><option value="coach" ${coach?'selected':''}>Ritu · Coach workspace</option>${clients.map(x=>`<option value="${x.id}" ${!coach&&c().id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></header><div class="content">${page()}</div></main><nav class="mobile-bottom" aria-label="Quick navigation">${(coach?[['overview','Home'],['clients','Clients'],['records','Records']]:[['today',t('Today','Aaj')],['checkin','Check-In'],['journals',t('Journals','Journals')]]).map(([id,label])=>`<button data-view="${id}" ${state.view===id?'aria-current="page"':''}>${label}</button>`).join('')}<button class="mobile-more" aria-expanded="false" aria-controls="workspace-navigation">${t('More','Aur')}</button></nav></div>`;
 translateUI();bind();bindWorkflow();bindTasks();save();}
function title(k,sub,action=''){return `<div class="heading"><div><div class="eyebrow">SEEK BY RITU / ${state.mode==='coach'?'STUDIO':'PERSONAL SPACE'}</div><h1>${k}</h1><div class="muted">${sub}</div></div>${action}</div>`}
function selector(){return `<div class="field"><label for="client-select">Client record</label><select id="client-select">${clients.map(x=>`<option value="${x.id}" ${c().id===x.id?'selected':''}>${x.name}</option>`).join('')}</select></div>`}
function page(){switch(state.view){case'work':return workPage();case'emails':return emailsPage();case'booking':return bookingPage();case'leads':return leadsPage();case'calendar':return calendarPage();case'practices':return practicesPage();case'onboarding':return onboardingPage();case'overview':return overview();case'clients':return clientPage();case'today':return today();case'habits':return habitPage();case'checkin':return checkin();case'records':return records();case'journals':return journals();case'resources':return resources();case'reports':return reports();case'profile':return profile();case'agreement':return agreement();case'notes':return notes();default:return overview()}}
function legacyOverview(){return title('A little clarity. A lot of progress.','Your clients, commitments and conversations—in one calm space.')+`<div class="stats"><div class="stat"><span>REGISTERED PROFILES</span><strong>${clients.length}</strong><span>${clients.filter(x=>programme(x.id).status==='Active').length} active programmes</span></div><div class="stat"><span>NEEDS YOUR ATTENTION</span><strong>2</strong><span>One request · one plan review</span></div><div class="stat"><span>UPCOMING CALLS</span><strong>${allCalls().filter(x=>x.date>=day).length}</strong><span>20-minute progress reviews</span></div><div class="stat"><span>PROGRAMME STANDARD</span><strong>95%</strong><span>Proposed commitment threshold</span></div></div><div class="grid"><section><div class="hero"><div class="eyebrow">YOUR PRACTICE, WITH INTENTION</div><h2>See the person.<br>Support the next action.</h2><p>Review what matters, adapt with care, and keep every commitment clear.</p>${button('Open client workspace','clients','')}</div><div class="card"><div class="row"><h2>Your clients</h2><span class="badge green">30-day programme</span></div>${clients.map(x=>clientRow(x)).join('')}</div></section><aside><div class="card"><div class="eyebrow">ATTENTION QUEUE</div><h2>Start here</h2><div class="list-item"><span class="badge">Help requested</span><h3>Meera · capacity check</h3><p class="small muted">Fatigue reported. Review her agreed adaptation before discussing completion.</p>${button('Review Meera','review-meera','subtle')}</div><div class="list-item"><span class="badge">Call preparation</span><h3>Daniel · outreach</h3><p class="small muted">Explore the next agreed action after a difficult response.</p>${button('Prepare call','call-daniel','subtle')}</div></div><div class="card"><h3>Coach reminder</h3><p class="small muted">Adaptations, submitted check-ins, completed habits and reviewed evidence are different records.</p></div></aside></div>`}
function clientRow(x){return `<div class="list-item row"><div class="person"><div class="avatar">${x.initials}</div><div><strong>${x.name}</strong><div class="small muted">${x.background}</div><span class="badge green">Day ${x.day} of 30</span></div></div><div class="actions"><button class="btn subtle" data-client="${x.id}">Open profile</button><button class="btn subtle" data-preview="${x.id}">View as client</button></div></div>`}
function clientPage(){return title('People, before paperwork.','Open a record or see the dashboard your client sees.')+`<div class="card">${clients.map(clientRow).join('')}</div>`}
function habitList(details=false,readonly=false){return habits().map((h,i)=>`<div class="habit"><input type="checkbox" aria-label="${esc(h[1])}" data-habit="${i}" ${readonly?'disabled':''} ${status(i)==='done'?'checked':''}><div class="body"><div class="eyebrow">${h[0]}</div><strong class="${status(i)==='done'?'completed':''}">${esc(h[1])}</strong><div class="small muted">${esc(h[2])}</div><details ${details?'open':''}><summary>${t('Know more','Aur jaano')}</summary><p class="small"><b>${t('Completion','Complete kab hoga')}:</b> ${esc(h[3])}<br><b>${t('Chosen block','Chuna hua block')}:</b> ${esc(h[4])}<br><b>${t('Agreed alternative','Agreed alternative')}:</b> ${esc(h[5])}<br><b>${t('Evidence','Evidence')}:</b> ${t('Self-report; no private screenshots required.','Self-report; private screenshots zaroori nahi.')}</p></details></div><select data-status="${i}" ${readonly?'disabled':''} aria-label="Status for ${esc(h[1])}">${[['pending',t('Pending','Baaki')],['done',t('Done','Ho gaya')],['adapted',t('Adapted','Adapt kiya')],['rest',t('Rest/recovery','Rest/recovery')],['missed',t('Missed','Miss hua')]].map(([v,l])=>`<option value="${v}" ${status(i)===v?'selected':''}>${l}</option>`).join('')}</select></div>`).join('')}
function today(){return title(t('Your day, with intention.','Aaj ka din, intention ke saath.'),t('Small, agreed actions. A clear next step.','Chhote, agreed actions. Ek clear agla step.'))+`<div class="hero"><div class="eyebrow">${t('YOUR IDENTITY','TUMHARI IDENTITY')} · DAY ${programmeDay(c().id)}</div><h2>${esc(identity())}</h2><p>${esc(clientGoal())}</p></div>${practiceCard()}<div class="grid"><div class="card"><div class="row"><h2>${t('Today’s commitments','Aaj ki commitments')}</h2><span class="badge green">${done()} / ${habits().length} ${t('done','ho gaye')}</span></div>${habitList()}</div><aside><div class="card"><div class="eyebrow">${t('NEXT CHECK-IN','AGLA CHECK-IN')}</div><h2>${t('Pause. Notice. Continue.','Ruko. Dekho. Aage badho.')}</h2><p class="muted small">${t('Your habit statuses are already here. No need to type them again.','Habit status apne aap aa jayega. Dobara bharna nahi hai.')}</p>${button(t('Open check-in','Check-In bharo'),'checkin','primary')}</div><div class="card"><h3>${t('Learn → apply → review','Seekho → apply karo → review')}</h3><p class="small muted">${t('Your next application and its outcome stay together in Learn & Apply.','Apna application aur uska result Learn & Apply mein dekho.')}</p>${button(t('Open journals','Journals kholo'),'journals','subtle')}</div><div class="note">${t('This is a demo preview. Real account access and private storage are not enabled.','Yeh demo preview hai. Real account access aur private storage enabled nahi hain.')}</div></aside></div>`}
function habitPage(){const coach=state.mode==='coach';return title(coach?'Personal plans. Clear commitments.':t('Know Your Habits.','Apni habits jaano.'),coach?'Edit the demo plan. Work blocks remain client-chosen.':t('Understand the why. Keep your daily tracking simple.','Kyun karna hai, samjho. Roz ka tracker simple rakho.'))+(coach?selector():'')+`<div class="card">${coach?button('Add Habit','add-habit','primary')+habits().map((h,i)=>`<div class="list-item row"><div><span class="eyebrow">${h[0]}</span><h3>${esc(h[1])}</h3><span class="small muted">${esc(h[2])}</span></div><button class="btn" data-edit="${i}">Edit habit</button></div>`).join(''):habitList(true)}</div><div id="editor"></div>`}
function checkin(){const ck=`${key()}:${state.tab}`,previous=state.checkins[ck];return title(t('A moment to check in.','Ek chhota sa check-in.'),t('The same habits. One short update.','Wahi habits. Ek short update.'))+`<div class="tabs">${['Morning','Midday','Evening','Bedtime'].map(x=>`<button class="btn ${state.tab===x?'active':''}" data-tab="${x}">${t(x,{Morning:'Subah',Midday:'Dopahar',Evening:'Shaam',Bedtime:'Sone se pehle'}[x])}${state.checkins[`${key()}:${x}`]?' ✓':''}</button>`).join('')}</div><div class="grid"><div class="card"><h2>${t('Your current progress','Abhi tak ki progress')}</h2>${practiceSnapshot()}${habitList()}</div><form class="card" id="check-form"><h2>${t('Your update','Tumhara update')}</h2>${previous?`<div class="note">${t('Latest submission','Latest submission')}: ${esc(new Date(previous.at).toLocaleString())}. ${t('Submitting again adds a revision.','Dobara submit karne par revision save hoga.')}</div>`:''}<div class="field"><label>${t('How are things?','Abhi kaisa chal raha hai?')}</label><select name="feeling"><option>On track</option><option>Need an adjustment</option><option>Need coach support</option></select></div>${state.tab==='Morning'?`<div class="field"><label>${t('Your personal shukrana','Aaj ka personal shukrana')}</label><textarea name="gratitude" maxlength="3000">${esc(previous?.gratitude||'')}</textarea></div>`:''}<div class="field"><label>${t('Where is there a difficulty? (optional)','Kahan difficulty hai? (optional)')}</label>${habits().map((h,i)=>`<label><input type="checkbox" name="difficulty" value="${i}"> ${esc(h[1])}</label>`).join('')}</div><div class="field"><label>${t('One short note and next action (optional)','Ek short note aur agla action (optional)')}</label><textarea name="note" maxlength="3000">${esc(previous?.note||'')}</textarea></div><div class="note">${t('A commitment is still pending? Record what happened honestly and choose your next action.','Commitment pending hai? Honestly record karo aur apna next action choose karo.')}</div><button class="btn primary" type="submit">${t('Submit check-in','Check-In submit karo')}</button></form></div>`}
function records(){return title('Daily Records.','Timestamped check-ins with the habit statuses captured at submission.')+selector()+`<div class="card">${Object.entries(state.checkins).filter(([k])=>k.startsWith(c().id+':')).map(([k,v])=>`<div class="list-item"><h3>${esc(k.split(':').slice(1).join(' · '))}</h3><div class="small muted">${esc(new Date(v.at).toLocaleString())} · ${esc(v.feeling)}</div><p>${esc(v.note||'No difficulty reported.')}</p><div class="actions">${habits().map((h,i)=>`<span class="badge">${esc(h[0])}: ${esc(v.snapshot[i]||'pending')}</span>`).join('')}</div></div>`).join('')||'<p class="empty">No submitted demo check-ins yet. Open a client preview to submit one.</p>'}</div>`}
function journals(){const j=state.journals[c().id]||{};const coach=state.mode==='coach';return title(t('Room to reflect.','Khud ke liye thodi jagah.'),t('Two separate spaces. Life reflection and learning into action.','Do alag jagah. Life reflection aur learning ko action mein lana.'))+(coach?selector():'')+`<div class="grid"><form class="card journal-form" data-kind="daily"><span class="eyebrow">DAILY JOURNAL</span><h2>${t('Dear Divine,','Dear Nirankar,')}</h2><p class="small muted">${t('What happened? How did you respond? What are you sincerely grateful for? What would you change tomorrow?','Aaj kya hua? Tumne kaise respond kiya? Kis cheez ka sincere shukrana hai? Kal kya badalna hai?')}</p><textarea aria-label="Daily journal" name="body" maxlength="20000" ${coach?'readonly':''}>${esc(j.daily?.body||'')}</textarea><p class="small muted">${j.daily?esc(new Date(j.daily.at).toLocaleString()):t('No entry yet.','Abhi entry nahi hai.')}</p>${!coach?'<button class="btn primary">'+t('Save journal','Journal save karo')+'</button>':''}</form><form class="card journal-form" data-kind="learn"><span class="eyebrow">LEARN & APPLY</span><h2>${t('Make learning lived.','Seekha hua, jee kar dekho.')}</h2><div class="field"><label>${t('Resource and what stood out','Resource aur kaunsi baat yaad rahi')}</label><textarea name="body" maxlength="10000" ${coach?'readonly':''}>${esc(j.learn?.body||'')}</textarea></div><div class="field"><label>${t('My application in the next 24 hours','Agle 24 hours mein mera application')}</label><textarea name="application" maxlength="3000" ${coach?'readonly':''}>${esc(j.learn?.application||'')}</textarea></div><div class="field"><label>${t('Review: what happened when I applied it?','Review: apply kiya toh kya hua?')}</label><textarea name="outcome" maxlength="3000" ${coach?'readonly':''}>${esc(j.learn?.outcome||'')}</textarea></div>${!coach?'<button class="btn primary">'+t('Save learning & application','Learning aur application save karo')+'</button>':''}</form></div><div class="note">Demo only. Production journal access requires an explicit client privacy agreement. No journal text is sent to AI.</div>`}
const packs=['Thoughts & interpretations','Identity & restrictive labels','Action & outcomes','Communication & support','Systems & habits','Remembrance & responsibility'];
function legacyResources(){const coach=state.mode==='coach';return title(coach?'A thoughtful resource library.':t('One teaching. Real-life action.','Ek teaching. Real-life action.'),coach?'Private master library · six proposed packs.':'Assigned packs release every five programme days.')+`<div class="card">${packs.map((p,i)=>{const locked=!coach&&i>Math.floor((programmeDay(c().id)-1)/5);return `<div class="resource"><div class="row"><h3>${i+1}. ${p}</h3><span class="badge">Days ${i*5+1}–${i*5+5} · ${locked?'Not released':coach?'Master draft':'Assigned'}</span></div>${!locked?'<p class="small muted">Original exercise: notice one situation, separate observable facts from interpretation, and choose one action aligned with your values.</p><p class="small">Reflection → HRCMS application → next-day review.</p>':''}</div>`}).join('')}</div><div class="note">Demo packs contain original sample exercises, not licensed book excerpts. Production assignments must be coach-selected and authorised.</div>`}
function reports(){let entries=Object.entries(state.records).filter(([k])=>k.startsWith(c().id+':'));let total=entries.length*habits().length,completed=entries.reduce((n,[,v])=>n+Object.values(v).filter(x=>x==='done').length,0);let score=total?Math.round(completed/total*100):null;return title(t('Progress you can see.','Progress jo dikh sake.'),`${esc(c().name)} · ${t('Live demo activity + illustrative baseline comparison','Live demo activity + illustrative baseline comparison')}`,`<div class="actions">${button('Print / Save PDF','print','primary')}${button('Download CSV','csv')}</div>`)+(state.mode==='coach'?selector():'')+`<div class="hero"><div class="eyebrow">PERSONAL PROGRESS / DEMO REPORT</div><h2>${esc(c().name)}</h2><p>${esc(clientGoal())}</p><span class="badge">Programme day ${programmeDay(c().id)} · ${day}</span></div><div class="stats"><div class="stat"><span>OBSERVED COMPLETION</span><strong>${score===null?'—':score+'%'}</strong><span>${completed} completed / ${total} recorded habit slots</span></div><div class="stat"><span>CHECK-INS SUBMITTED</span><strong>${Object.keys(state.checkins).filter(k=>k.startsWith(c().id+':')).length}</strong><span>Actual demo submissions</span></div><div class="stat"><span>RECORDED DAYS</span><strong>${entries.length}</strong><span>Unrecorded days are missing data</span></div><div class="stat"><span>PROPOSED THRESHOLD</span><strong>95%</strong><span>No automatic refund decision</span></div></div><div class="card"><h2>HRCMS · starting point & direction</h2><p class="small muted">Illustrative self-ratings out of 10. These are sample values, not validated outcomes or measured improvement.</p><div class="pillar-grid">${['Health','Relationships','Career','Money','Spirituality'].map((p,i)=>`<div class="pillar"><div class="eyebrow">${p}</div><strong>${c().current[i]}<span class="small"> / 10</span></strong><progress max="10" value="${c().current[i]}" aria-label="${p} sample self-rating"></progress><span class="small">Sample baseline ${c().baseline[i]} → ${c().current[i]}</span></div>`).join('')}</div></div><div class="grid"><div class="card"><h2>Actions behind the numbers</h2>${habits().map((h,i)=>`<div class="list-item row"><span>${esc(h[1])}</span><span class="badge">${esc(status(i))}</span></div>`).join('')}</div><div class="card"><h2>What needs a conversation?</h2><p>${esc(clientDifficulty())}</p><div class="note">This demo is not a completed weekly or day-30 report. Automatic scheduled reporting, verified baselines and policy-based eligibility require the production backend.</div></div></div>`}
function profile(){return title(t('Your starting point. Your plan.','Tumhara starting point. Tumhara plan.'),'Read-only demo profile · original intake preserved.')+`<div class="card"><div class="person"><div class="avatar">${c().initials}</div><div><h2>${c().name}</h2><span class="muted">${c().background}</span></div></div><div class="resource"><label>30-day goal</label><p>${esc(clientGoal())}</p><label>Identity statement</label><p>${esc(identity())}</p><label>Reported constraint</label><p>${esc(clientDifficulty())}</p></div><span class="badge green">Fictional demo profile</span><p class="small muted">This demonstration has a short sample profile. The full 30-question intake and immutable submission history are not implemented yet.</p>${button(t('Request correction','Correction request karo'),'correction')}</div><div class="card"><h2>Assigned Plan</h2>${habitList(true,true)}</div>`}
function agreement(){const a=state.agreements[c().id];return title(t('Clear agreements. Shared responsibility.','Clear agreements. Dono ki responsibility.'),'Draft programme terms · demonstration only.')+(state.mode==='coach'?selector():'')+`<div class="card"><h2>One onboarding week + 30 tracking days</h2><p>Personalised HRCMS commitments, four brief daily check-ins, separate journals and a 20-minute call every third programme day.</p><div class="form-grid"><div class="note"><b>Programme fee</b><br>$350 · currency to be confirmed</div><div class="note"><b>Refundable deposit</b><br>$150 · eligibility terms pending</div></div><h3>Accountability</h3><p>95% is the proposed passing threshold. The eligible action denominator, agreed adaptations, emergency exceptions, repeat process and deposit treatment are not final. No automated financial consequence is applied.</p><h3>Privacy & access</h3><p>Production terms must state coach access, retention, export/deletion options and any external processing. This demo stores fictional entries in your browser only.</p><div class="note">Not a binding contract or verified electronic signature. Legal review and production signing infrastructure are required before enrolling paying clients.</div>${a?`<p>Demo acknowledgement by <strong>${esc(a.name)}</strong> · ${esc(new Date(a.at).toLocaleString())}</p>`:''}${state.mode!=='coach'?`<form id="agreement-form"><div class="field"><label for="signer">Demo acknowledgement name</label><input id="signer" name="name" required maxlength="100"></div><label><input type="checkbox" required> I understand these are draft demo terms, not a final payment agreement.</label><button class="btn primary">Record demo acknowledgement</button></form>`:''}</div>`}
function notes(){return title('A private space for your judgement.','Coach-only in the demo interface. Production authorisation is not implemented.')+selector()+`<form class="card" id="notes-form"><h2>Call preparation & private notes</h2><div class="note">Suggested discussion: ${esc(clientDifficulty())} Ask what happened, what support would help, and agree the next action.</div><textarea name="body" aria-label="Private coach notes" maxlength="20000">${esc(state.notes[c().id]||'')}</textarea><button class="btn primary">Save demo coach note</button></form>`}
function navigate(view){state.view=view;render();window.scrollTo(0,0)}
function bind(){document.querySelectorAll('.mobile-menu-toggle,.mobile-more').forEach(el=>el.onclick=()=>{const open=$('.sidebar').classList.toggle('mobile-menu-open');document.querySelectorAll('.mobile-menu-toggle,.mobile-more').forEach(b=>b.setAttribute('aria-expanded',String(open)));if(open){window.scrollTo({top:0,behavior:'smooth'});$('#workspace-navigation button')?.focus()}});document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>navigate(el.dataset.view));
$('#persona').onchange=e=>{state.mode=e.target.value==='coach'?'coach':'client';if(state.mode==='client'){state.client=e.target.value;state.languages[c().id]??=c().language}state.view=state.mode==='coach'?'overview':'today';render()};
$('#language')?.addEventListener('change',e=>{captureDrafts();state.languages[c().id]=e.target.value;save();render();restoreDrafts()});
$('#client-select')?.addEventListener('change',e=>{state.client=e.target.value;save();render()});
 document.querySelectorAll('[data-client]').forEach(el=>el.onclick=()=>{state.client=el.dataset.client;navigate('profile')});
 document.querySelectorAll('[data-preview]').forEach(el=>el.onclick=()=>{state.client=el.dataset.preview;state.mode='client';state.languages[c().id]??=c().language;navigate('today')});
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{const a=el.dataset.action;if(a==='add-habit'){editNewHabit();return}if(a==='print'){window.print();return}if(a==='csv'){exportCSV();return}if(a==='review-meera'){state.client='meera';navigate('habits');return}if(a==='call-daniel'){state.client='daniel';navigate('notes');return}if(a==='correction'){toast(t('Demo: correction requests are not sent to a coach.','Demo: correction request coach ko send nahi hoti.'));return}navigate(a)});
 document.querySelectorAll('[data-habit]').forEach(el=>el.onchange=()=>setStatus(el.dataset.habit,el.checked?'done':'pending'));
 document.querySelectorAll('[data-status]').forEach(el=>el.onchange=()=>setStatus(el.dataset.status,el.value));
 document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{state.tab=el.dataset.tab;render()});
 $('#check-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const k=`${key()}:${state.tab}`,old=state.checkins[k];state.checkins[k]={at:new Date().toISOString(),note:f.get('note'),gratitude:f.get('gratitude'),feeling:f.get('feeling'),difficulties:f.getAll('difficulty'),snapshot:{...statuses()},practiceSnapshot:{...(state.practiceTicks[key()]||{})},history:old?[...(old.history||[]),{...old,history:undefined}]:[]};save();render();toast(t('Check-In saved. Your habit statuses were captured.','Check-In save ho gaya. Habit statuses bhi record ho gaye.'))});
 document.querySelectorAll('.journal-form').forEach(form=>form.onsubmit=e=>{e.preventDefault();if(state.mode==='coach')return;const f=new FormData(form),kind=form.dataset.kind;state.journals[c().id]??={};state.journals[c().id][kind]={body:f.get('body'),application:f.get('application'),outcome:f.get('outcome'),at:new Date().toISOString()};save();toast(t('Saved in this demo browser.','Is demo browser mein save ho gaya.'))});
 document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>editHabit(Number(el.dataset.edit)));
 $('#agreement-form')?.addEventListener('submit',e=>{e.preventDefault();state.agreements[c().id]={name:new FormData(e.target).get('name'),at:new Date().toISOString()};save();render();toast('Demo acknowledgement recorded. This is not a legal signature.')});
 $('#notes-form')?.addEventListener('submit',e=>{e.preventDefault();state.notes[c().id]=new FormData(e.target).get('body');save();toast('Demo coach note saved.')});
}
function setStatus(i,value){state.records[key()]??={};state.records[key()][i]=value;save();render()}
function editHabit(i){const h=habits()[i];$('#editor').innerHTML=`<form id="habit-editor" class="card"><h2>Edit ${esc(h[0])} habit</h2><p class="small muted">Changes the fictional demo plan only. Production plan versioning and client re-agreement are still required.</p>${['HRCMS pillar','Short habit name','Why it matters','Completion standard','Client-chosen work block','Agreed alternative'].map((label,n)=>`<div class="field"><label for="habit-field-${n}">${label}</label><input id="habit-field-${n}" name="f${n}" maxlength="1000" value="${esc(h[n])}" required></div>`).join('')}<div class="actions"><button class="btn primary">Save demo habit</button><button class="btn" type="button" id="cancel-edit">Cancel</button></div></form>`;$('#editor').scrollIntoView({behavior:'smooth'});$('#cancel-edit').onclick=()=>{$('#editor').innerHTML=''};$('#habit-editor').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.localizedEdits[c().id]??={};state.localizedEdits[c().id][hi()?'hi':'en']??={};state.localizedEdits[c().id][hi()?'hi':'en'][i]=Array.from({length:6},(_,n)=>f.get('f'+n));save();render();toast('Demo habit updated.')}}
function exportCSV(){const rows=[['Client','Date','Pillar','Habit','Status']];Object.entries(state.records).filter(([k])=>k.startsWith(c().id+':')).forEach(([k,v])=>habits().forEach((h,i)=>rows.push([c().name,k.split(':')[1],h[0],h[1],v[i]||'pending'])));if(rows.length===1){toast('No recorded activity to export. Update a habit in the client preview first.');return}const csv=rows.map(row=>row.map(x=>'"'+String(x).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`seek-${c().id}-${day}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

function identity(){if(!['daniel','meera'].includes(c().id))return c().identity;return c().id==='daniel'?t('I am a person who follows through with care and intention.','Main care aur intention ke saath apni commitments nibhata hoon.'):t('I am a woman who honours her body and lives her commitments with awareness.','Main apne sharir ki izzat karti hoon aur awareness ke saath commitments nibhati hoon.')}
function clientGoal(){if(!['daniel','meera'].includes(c().id))return c().goal;return c().id==='daniel'?t('Build a steady routine while transitioning to freelance work.','Freelance work ki taraf badhte hue consistent routine banana.'):t('Build a routine and boundaries that respect daily capacity.','Daily capacity ke hisaab se routine aur boundaries banana.')}
function practiceCard(){return `<section class="card"><div class="eyebrow">IDENTITY INTO ACTION</div><h2>Daily Practices</h2><p>Coach-assigned practices are separate from your HRCMS habits. Affirmations, remembrance and reflection appear only as assigned.</p><div class="actions">${assignedPractices().map(p=>`<span class="badge">${esc(p.name)}</span>`).join('')||'<span class="muted">No practices assigned yet.</span>'}</div><br>${button('Open Daily Practices','practices','primary')}</section>`}
let drafts={};
function captureDrafts(){drafts={};document.querySelectorAll('form').forEach(f=>{drafts[f.id||f.dataset.kind]=Array.from(f.elements).map(e=>({name:e.name,value:e.value,checked:e.checked,type:e.type}))})}
function restoreDrafts(){document.querySelectorAll('form').forEach(f=>{const values=drafts[f.id||f.dataset.kind];if(!values)return;Array.from(f.elements).forEach((e,i)=>{const v=values[i];if(!v||e.name!==v.name)return;if(e.type==='checkbox')e.checked=v.checked;else if(!['submit','button'].includes(e.type))e.value=v.value})})}
