function clientDifficulty(){return c().id==='meera'?'Fatigue reported today. Review the agreed movement adaptation.':c().difficulty||'No constraint recorded yet.'}
function dateAdd(date,days){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
function programme(id){return state.programmes[id]||{status:'Not Activated',start:day,time:'10:00',deposit:false,balance:false,agreed:false}}
function programmeDay(id){const p=programme(id);if(p.status==='Not Activated')return clients.find(x=>x.id===id)?.day||1;const at=p.status==='On Hold'?p.held:day;return Math.max(1,Math.min(30,Math.floor((Date.parse(at+'T12:00:00Z')-Date.parse(p.start+'T12:00:00Z'))/86400000)+1))}
function callsFor(id){const p=programme(id);if(!['Active','On Hold','Ended'].includes(p.status))return[];return (p.calls||Array.from({length:10},(_,i)=>({id,number:i+1,programmeDay:(i+1)*3,date:dateAdd(p.start,(i+1)*3-1),time:p.time||'10:00'}))).filter(x=>p.status==='Active'||x.date<(p.held||day))}
function allCalls(){return clients.flatMap(x=>callsFor(x.id)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))}
function callConflict(id,proposed){return callsFor(id).some(x=>calendarEvents().some(y=>!y.nonblocking&&(y.id!==id||y.label!=='Coaching Call')&&y.date===x.date&&minutes(x.time)<minutes(y.time)+(y.duration||20)&&minutes(x.time)+20>minutes(y.time)))}
