function moneyPanel(id){const p=programme(id),intake=state.intakes[id];return `<div class="actions"><button class="btn subtle" data-payment="${id}" data-kind="deposit">${p.deposit?'Deposit Confirmed':'Confirm $150 Deposit (Demo)'}</button><button class="btn subtle" data-payment="${id}" data-kind="agreed">${p.agreed?'Plan Agreed':'Record Plan Agreement'}</button><button class="btn subtle" data-payment="${id}" data-kind="balance">${p.balance?'Balance Confirmed':'Confirm $350 Balance (Demo)'}</button><button class="btn subtle" data-intake="${id}">View Questionnaire</button></div><p class="small muted">Questionnaire: ${intake?.submitted?'Submitted':intake?'Draft':'Not Started'} · Total $500; currency and final terms pending. No payment processing connected.</p>`}
function leadsPage(){return title('Leads & Enrollment','Register, prepare onboarding, agree the plan, and activate the programme.')+`<div class="grid"><form id="lead-form" class="card"><h2>Register Lead</h2><div class="form-grid">${[['first','First Name'],['last','Last Name'],['email','Email'],['phone','Phone Number']].map(([n,l])=>`<div class="field"><label for="lead-${n}">${l}</label><input id="lead-${n}" name="${n}" type="${n==='email'?'email':n==='phone'?'tel':'text'}" required maxlength="200"></div>`).join('')}</div><div class="field"><label>Inquiry Source</label><select name="source"><option>WhatsApp</option><option>Email</option><option>Other</option></select></div><button class="btn primary">Register Demo Lead</button><div class="note">Use fictional details only. This browser demo does not send emails or securely store real leads.</div></form><div class="card"><h2>Enrollment Sequence</h2><p>Inquiry → $150 deposit → onboarding questions → consultation and plan → client agreement → $350 balance → account invitation → Day 1.</p><p class="small muted">One onboarding week is separate from the 30 tracking days. The remaining $350 is due by the day before the agreed start. A late payment requires a new start date.</p></div></div><div class="card">${clients.map(x=>{const l=state.leads.find(y=>y.id===x.id),p=programme(x.id);return `<div class="list-item"><div class="row"><h3>${esc(x.name)}</h3><span class="badge green">${esc(p.status==='Not Activated'?(p.balance?'Ready For Activation':p.agreed?'Awaiting Balance':state.intakes[x.id]?.submitted?'Plan Preparation':p.deposit?'Onboarding':'Awaiting Deposit'):p.status)}</span></div>${l?`<p class="small muted">${esc(l.email)} · ${esc(l.phone)} · ${esc(l.source)}</p><a class="btn subtle" href="${esc(firstStepsMail(l))}">Open First-Steps Email Draft</a>`:'<p class="small muted">Fictional sample profile · no email address recorded</p>'}${moneyPanel(x.id)}<div class="actions"><button class="btn subtle" data-client="${x.id}">Open Profile</button><button class="btn subtle" data-manage="${x.id}">Manage Programme & Calls</button></div></div>`}).join('')}</div>`}
function firstStepsMail(l){return 'mailto:'+encodeURIComponent(l.email)+'?subject='+encodeURIComponent('Seek by Ritu — Your First Steps')+'&body='+encodeURIComponent(`Hello ${l.first},\n\nWelcome to Seek by Ritu. Your programme includes one onboarding week followed by 30 coaching days.\n\n1. Review and accept the final programme and payment terms.\n2. Pay the $150 deposit using the instructions Ritu provides.\n3. After payment confirmation, complete the private onboarding questionnaire supplied by Ritu.\n4. We will discuss your personalised habits, daily practices, resources and work blocks.\n5. The remaining $350 is due by the day before your agreed programme start date.\n\nThis is a draft: currency, approved payment destination, final terms and private questionnaire link must be added before sending.\n\nRitu\nSeek by Ritu`)}
function calendarPage(){const mode=state.calendarMode||'Week',anchor=state.calendarDate||day;const list=calendarEvents().filter(x=>(!state.calendarClient||x.id===state.calendarClient)&&(mode==='Day'?x.date===anchor:mode==='Week'?x.date>=anchor&&x.date<=dateAdd(anchor,6):x.date.slice(0,7)===anchor.slice(0,7)));return title('Calendar','20-minute calls on programme days 3, 6, 9 … 30. Demo calendar uses UTC; no external calendar is connected.')+`<div class="card"><div class="row"><div class="tabs">${['Day','Week','Month'].map(m=>`<button class="btn ${mode===m?'primary':''}" data-calendar-mode="${m}">${m}</button>`).join('')}</div><div class="actions"><input type="date" id="calendar-date" aria-label="Calendar date" value="${anchor}"><select id="calendar-client" aria-label="Filter client"><option value="">All Clients</option>${clients.map(x=>`<option value="${x.id}" ${state.calendarClient===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div>${mode==='Month'?monthGrid(anchor,list):''}${list.length?list.map(x=>`<div class="list-item row"><div><h3>${esc(clients.find(c=>c.id===x.id)?.name)}</h3><span class="muted small">${x.date} · ${x.time} UTC · ${x.nonblocking?'Deadline':(x.duration||20)+' minutes'} · ${esc(x.label||'Coaching Call')}${x.programmeDay?' · Programme Day '+x.programmeDay:''}</span></div><button class="btn subtle" data-call-client="${x.id}">Prepare Call</button></div>`).join(''):'<div class="empty">No calls in this view. Activate a programme below, or change the date range.</div>'}</div><div class="card"><h2>Programme Controls</h2><p class="small muted">Confirm deposit, questionnaire, plan agreement and balance in Leads & Enrollment before activation. Choose one agreed recurring time; overlapping calls are rejected. Future calls disappear on hold and return shifted by the hold duration on resume.</p>${clients.map(x=>{const p=programme(x.id);return `<form class="programme-form list-item" data-id="${x.id}"><div class="row"><h3>${esc(x.name)}</h3><span class="badge">${esc(p.status)}</span></div><div class="form-grid"><div class="field"><label>Agreed Programme Start</label><input name="start" type="date" value="${p.start}" required></div><div class="field"><label>Agreed Call Time (UTC)</label><input name="time" type="time" value="${p.time}" required></div></div><div class="actions"><button class="btn primary">${p.status==='Not Activated'?'Activate Programme':'Update Future Schedule'}</button>${p.status==='Active'?`<button class="btn" type="button" data-hold="${x.id}">Put On Hold</button>`:''}${p.status==='On Hold'?`<button class="btn" type="button" data-resume="${x.id}">Resume Programme</button>`:''}${['Active','On Hold'].includes(p.status)?`<button class="btn" type="button" data-end="${x.id}">End Programme</button>`:''}</div></form>`}).join('')}</div>`}
function monthGrid(anchor,calls){const y=Number(anchor.slice(0,4)),m=Number(anchor.slice(5,7));const days=new Date(Date.UTC(y,m,0)).getUTCDate();const offset=new Date(Date.UTC(y,m-1,1)).getUTCDay();return `<div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<strong>${d}</strong>`).join('')}${Array.from({length:offset},()=>'<div></div>').join('')}${Array.from({length:days},(_,i)=>{const d=anchor.slice(0,8)+String(i+1).padStart(2,'0');return `<div class="calendar-cell"><b>${i+1}</b>${calls.filter(x=>x.date===d).map(x=>`<span>${esc(clients.find(c=>c.id===x.id).name.split(' ')[0])} ${x.time}</span>`).join('')}</div>`}).join('')}</div>`}
