function workflow(id){state.workflow??={};return state.workflow[id]??={}}
function enqueue(id,type,subject,body,due=day){state.outbox??={};const key=id+':'+type;if(!state.outbox[key])state.outbox[key]={id:key,client:id,type,subject,body,due,status:'Draft',created:new Date().toISOString()}}
function syncWork(){state.workflow??={};state.outbox??={};for(const x of clients){const w=workflow(x.id),p=programme(x.id),l=state.leads.find(l=>l.id===x.id),intake=state.intakes[x.id];if(l)enqueue(x.id,'first','Your First Steps','Review your one-page programme agreement and payment terms before paying the $150 deposit. After verification, complete your onboarding questionnaire. Total programme price: $500, currency and final terms to be confirmed. Payment destination must be supplied by Ritu.');if(p.deposit){w.depositDate??=day;if(!intake?.submitted)enqueue(x.id,'questionnaire-reminder','Reminder — Complete Your Onboarding','Your questionnaire is pending. Complete it before plan preparation can begin.',dateAdd(w.depositDate,2));}if(p.deposit)enqueue(x.id,'deposit','Deposit Confirmed — Complete Your Onboarding','Your $150 deposit has been recorded in this demo. Receipt: deposit $150, balance $350. Complete your private questionnaire when your coach provides the secure link. After submission, allow three calendar days for plan preparation.');if(intake?.submitted){w.planDue??=dateAdd(intake.submitted.slice(0,10),3);enqueue(x.id,'answers','Your Onboarding Answers Have Been Received',`Your coach is preparing your personalised plan. Expected ready date: ${w.planDue}. A walkthrough invitation follows once the plan is ready.`)}if(w.planReady&&w.slots?.length)enqueue(x.id,'slots','Your Plan Is Ready — Book Your Walkthrough','Your plan is ready for discussion, not attached to this email. Choose one of the four coach-offered slots in the demo Booking screen. The walkthrough lasts 30 minutes.');if(w.slots?.length&&!w.booking)enqueue(x.id,'slot-reminder','Reminder — Choose Your Walkthrough Slot','Please choose one available walkthrough slot. Slots are rechecked when you book.',dateAdd(w.slotsAt||day,2));if(w.booking)enqueue(x.id,'booking','Your Walkthrough Is Booked',`Your 30-minute walkthrough is booked for ${w.booking.date} at ${w.booking.time} UTC. We will discuss your plan and commitments.`);if(w.walkthroughDone&&p.agreed)enqueue(x.id,'balance','Confirm Your Start — Remaining Payment','Your walkthrough and plan agreement are recorded. Remaining balance: $350. After verified payment, your programme begins the following day. Payment destination, currency and final invoice details require coach review.');if(p.balance){w.balanceDate??=day;const start=dateAdd(w.balanceDate,1);if(w.walkthroughDone&&p.deposit&&p.agreed&&intake?.submitted&&p.status==='Not Activated'){const proposal={...p,status:'Active',start};state.programmes[x.id]=proposal;if(callConflict(x.id)){state.programmes[x.id]=p;w.activationIssue='Call conflict: select another recurring time in Calendar.'}else{w.autoActivated=true;delete w.activationIssue;}}enqueue(x.id,'paid','Balance Confirmed — Your Programme Starts Tomorrow',`Demo payment receipt: balance $350; total received $500. Programme start: ${start}, UTC. The production account setup link will let you set your own password; no password is emailed.`);enqueue(x.id,'welcome','Welcome — Your Programme Starts Today',`Your start date is ${start}. Visit My Day, My Habits, Daily Practices, Check-Ins, Journals and My Resources. Production login and private links are not connected.`,start)}}}
function reconcileMessages(){for(const e of Object.values(state.outbox||{})){const w=workflow(e.client),p=programme(e.client);if(['Simulated','Failed'].includes(e.status))continue;if((e.type==='questionnaire-reminder'&&state.intakes[e.client]?.submitted)||(e.type==='slot-reminder'&&w.booking)){e.status='Cancelled';continue}if(['On Hold','Ended'].includes(p.status)&&e.due>=day&&['welcome','slot-reminder','questionnaire-reminder'].includes(e.type)){e.status=p.status==='Ended'?'Cancelled':'Paused'}else if(e.status==='Paused')e.status='Draft'}}
function taskList(){const tasks=[];for(const x of clients){const id=x.id,w=workflow(id),p=programme(id),intake=state.intakes[id],l=state.leads.find(l=>l.id===id);const add=(kind,label,due,view,waiting=false)=>tasks.push({id:id+':'+kind,client:id,label,due,view,waiting});if(l&&!w.firstStepsReviewed)add('first','Review First Steps & Agreement',l.created.slice(0,10),'emails');if(!p.deposit){if(l)add('deposit','Waiting For $150 Deposit',day,'leads',true);continue}if(!intake?.submitted){add('answers','Waiting For Questionnaire',dateAdd(w.depositDate||day,2),'onboarding',true);continue}if(!w.planReady){add('plan','Prepare Personalised Plan',w.planDue||dateAdd(intake.submitted.slice(0,10),3),'habits');continue}if(!w.slots?.length){add('slots','Offer Four Walkthrough Slots',day,'work');continue}if(!w.booking){add('booking','Waiting For Slot Selection',day,'work',true);continue}if(!w.walkthroughDone){add('walkthrough','Complete Walkthrough & Record Changes',w.booking.date,'work');continue}if(!p.agreed){add('agreement','Confirm Plan Agreement',day,'leads');continue}if(!p.balance){add('balance','Waiting For $350 Balance',day,'leads',true);continue}if(p.status==='Not Activated')add('activation','Review Start & Activate Programme',dateAdd(w.balanceDate||day,1),'calendar')}
for(const e of Object.values(state.outbox||{})){if(e.status==='Failed')tasks.push({id:e.id+':failed',client:e.client,label:'Resolve Failed Demo Email: '+e.subject,due:day,view:'emails',waiting:false})}return tasks}
function overview(){return workPage()}
function workPage(){const tasks=taskList(),overdue=tasks.filter(t=>!t.waiting&&t.due<day),today=tasks.filter(t=>!t.waiting&&t.due===day),later=tasks.filter(t=>!t.waiting&&t.due>day),waiting=tasks.filter(t=>t.waiting);return title('Today’s Work','Your next actions, deadlines and client follow-through in one place.')+`<div class="stats"><div class="stat"><span>OVERDUE</span><strong>${overdue.length}</strong><span>Needs a revised action</span></div><div class="stat"><span>DUE TODAY</span><strong>${today.length}</strong><span>Clear next steps</span></div><div class="stat"><span>WAITING ON CLIENT</span><strong>${waiting.length}</strong><span>Payments, answers and bookings</span></div><div class="stat"><span>UPCOMING EVENTS</span><strong>${calendarEvents().filter(e=>e.date>=day).length}</strong><span>Calls and work blocks</span></div></div><div class="grid"><section>${taskGroup('Overdue',overdue)}${taskGroup('Due Today',today)}${taskGroup('Upcoming Tasks',later)}<div class="card"><h2>Upcoming Calls & Work Blocks</h2>${calendarEvents().filter(e=>e.date>=day).slice(0,8).map(e=>`<div class="list-item"><strong>${esc(e.label||'Coaching Call')} · ${esc(clients.find(c=>c.id===e.id)?.name)}</strong><div class="small muted">${e.date} · ${e.time} UTC · ${e.nonblocking?'Deadline':(e.duration||20)+' minutes'}</div></div>`).join('')||'<p class="muted">No scheduled events yet.</p>'}</div></section><aside>${taskGroup('Waiting On Client',waiting)}<div class="card"><h2>Work & Booking Controls</h2>${selector()}${workflowControls()}</div><div class="note">Local demo automation runs when this browser opens or changes state. No background email delivery, real bank verification, secure account provisioning or Google Calendar sync is connected.</div></aside></div>`}
function taskGroup(title,items){return `<div class="card"><h2>${title}</h2>${items.map(t=>`<div class="list-item"><div class="row"><strong>${esc(clients.find(c=>c.id===t.client)?.name)}</strong><span class="badge">${t.due}</span></div><p>${esc(t.label)}</p><button class="btn subtle" data-task-client="${t.client}" data-task-view="${t.view}">Open Next Action</button></div>`).join('')||'<p class="muted small">Nothing here right now.</p>'}</div>`}
function workflowControls(){const w=workflow(c().id),intake=state.intakes[c().id];return `<p class="small">Plan deadline: <strong>${w.planDue||'Created after questionnaire submission'}</strong> · Three calendar days</p><form id="plan-deadline-form"><label>Plan Deadline</label><input type="date" name="due" value="${w.planDue||dateAdd(day,3)}" required><button class="btn subtle">Revise Deadline</button></form><form id="work-block-form"><label>Plan Work Block (UTC)</label><input type="date" name="date" value="${w.workBlock?.date||day}" required><input type="time" name="time" value="${w.workBlock?.time||'09:00'}" required><label>Minutes</label><input type="number" name="duration" min="15" max="240" value="${w.workBlock?.duration||60}" required><button class="btn subtle">Save Work Block</button></form><br><button class="btn primary" data-plan-ready ${!intake?.submitted?'disabled':''}>${w.planReady?'Plan Ready ✓':'Mark Plan Ready'}</button><form id="offer-slots-form"><h3>Offer Four Slots</h3>${Array.from({length:4},(_,i)=>`<div class="slot-row"><input type="date" name="date${i}" aria-label="Slot ${i+1} date" required value="${w.slots?.[i]?.date||dateAdd(day,i+1)}"><input type="time" name="time${i}" aria-label="Slot ${i+1} time" required value="${w.slots?.[i]?.time||'14:00'}"></div>`).join('')}<button class="btn subtle" ${!w.planReady?'disabled':''}>Save & Queue Invitation</button></form>${w.booking?`<div class="note">Walkthrough: ${w.booking.date} · ${w.booking.time} UTC · 30 minutes</div><button class="btn primary" data-walkthrough-done>${w.walkthroughDone?'Walkthrough Completed ✓':'Complete Walkthrough'}</button>`:''}`}
function bookingPage(){const w=workflow(c().id);return title('Walkthrough Booking','Choose one coach-offered slot for a 30-minute discussion. Your plan is not emailed.')+`<div class="card">${w.booking?`<h2>Booking Confirmed</h2><p>${w.booking.date} · ${w.booking.time} UTC · 30 minutes</p>`:w.slots?.length?w.slots.map((slot,i)=>`<div class="list-item row"><span>${slot.date} · ${slot.time} UTC</span><button class="btn primary" data-book-slot="${i}" ${slotAvailable(c().id,slot.date,slot.time,30)?'':'disabled'}>Choose Slot</button></div>`).join(''):'<p>Your coach will offer four slots when your plan is ready.</p>'}</div>`}
function calendarEvents(){return [...allCalls().map(x=>({...x,label:'Coaching Call',duration:20})),...clients.flatMap(x=>{const w=workflow(x.id);return [...(w.planDue&&!w.planReady?[{id:x.id,date:w.planDue,time:'23:59',duration:0,label:'Plan Deadline',nonblocking:true}]:[]),...(w.workBlock&&!w.planReady?[{...w.workBlock,id:x.id,label:'Prepare Personalised Plan'}]:[]),...(w.booking?[{...w.booking,id:x.id,label:'Plan Walkthrough',duration:30}]:[])]})].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))}
function slotAvailable(id,date,time,duration,ignore=''){return !calendarEvents().some(e=>!e.nonblocking&&e.date===date&&!(e.id===id&&e.label===ignore)&&minutes(time)<minutes(e.time)+(e.duration||20)&&minutes(time)+duration>minutes(e.time))}
function emailsPage(){return title('Email Center','Preview event-triggered messages. Drafts and simulations are not actual delivery.')+`<div class="note">No email provider is connected. “Simulate Delivery” records a test result only. Production receipts require currency, seller details, final terms and verified payment references.</div><div class="card">${Object.values(state.outbox||{}).map(e=>`<div class="list-item"><div class="row"><h3>${esc(e.subject)}</h3><span class="badge">${esc(e.status)} · ${e.due>day?'Scheduled '+e.due:'Due '+e.due}</span></div><p class="small muted">${esc(clients.find(c=>c.id===e.client)?.name)} · ${esc(e.type)} · ${esc(e.id)}</p><p>${esc(e.body)}</p><div class="actions"><button class="btn subtle" data-email-reviewed="${e.id}">Mark Reviewed</button><button class="btn subtle" data-email-sim="${e.id}" ${e.due>day||['Cancelled','Paused'].includes(e.status)?'disabled':''}>${e.status==='Failed'?'Retry Demo Delivery':'Simulate Delivery'}</button><button class="btn subtle" data-email-fail="${e.id}" ${e.due>day||['Cancelled','Paused'].includes(e.status)?'disabled':''}>Simulate Failure</button></div></div>`).join('')||'<p>No messages queued. Register a fictional lead to begin.</p>'}</div>`}
function bindTasks(){$('#plan-deadline-form')?.addEventListener('submit',e=>{e.preventDefault();workflow(c().id).planDue=new FormData(e.target).get('due');save();render()});document.querySelectorAll('[data-task-client]').forEach(b=>b.onclick=()=>{state.client=b.dataset.taskClient;navigate(b.dataset.taskView)});
 $('#work-block-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),date=f.get('date'),time=f.get('time'),duration=Number(f.get('duration'));if(!slotAvailable(c().id,date,time,duration,'Prepare Personalised Plan')){toast('That work block overlaps another event. Choose another slot.');return}workflow(c().id).workBlock={date,time,duration};save();render();toast('Plan preparation block added to the internal calendar.')});
 $('[data-plan-ready]')?.addEventListener('click',()=>{if(!state.intakes[c().id]?.submitted)return;workflow(c().id).planReady??=new Date().toISOString();save();render()});
 $('#offer-slots-form')?.addEventListener('submit',e=>{e.preventDefault();if(!workflow(c().id).planReady)return;const f=new FormData(e.target),slots=Array.from({length:4},(_,i)=>({date:f.get('date'+i),time:f.get('time'+i)}));if(new Set(slots.map(s=>s.date+s.time)).size!==4||slots.some(s=>s.date<day||!slotAvailable(c().id,s.date,s.time,30,'Plan Walkthrough'))){toast('Offer four distinct, available slots dated today or later.');return}const w=workflow(c().id);if(w.booking){toast('A walkthrough is already booked. Preserve the confirmed booking.');return}w.slots=slots;w.slotsAt=day;save();render();toast('Four slots saved. Invitation queued as a demo draft.')});
 document.querySelectorAll('[data-book-slot]').forEach(b=>b.onclick=()=>{const w=workflow(c().id),slot=w.slots?.[Number(b.dataset.bookSlot)];if(w.booking||!slot||slot.date<day||!slotAvailable(c().id,slot.date,slot.time,30)){toast('This slot is no longer available.');return}w.booking={...slot};save();render();toast('Walkthrough booked in the demo calendar.')});
 $('[data-walkthrough-done]')?.addEventListener('click',()=>{const w=workflow(c().id);if(w.booking){w.walkthroughDone??=new Date().toISOString();save();render();toast('Walkthrough complete. Confirm plan agreement in Leads & Enrollment.')}});
 document.querySelectorAll('[data-email-reviewed]').forEach(b=>b.onclick=()=>{const e=state.outbox[b.dataset.emailReviewed];e.reviewedAt=new Date().toISOString();if(e.type==='first')workflow(e.client).firstStepsReviewed=true;save();render();toast('Reviewed. No email was sent.')});
 document.querySelectorAll('[data-email-sim]').forEach(b=>b.onclick=()=>{const e=state.outbox[b.dataset.emailSim];if(e.due>day)return;e.status='Simulated';e.attempts=(e.attempts||0)+1;e.simulatedAt=new Date().toISOString();save();render();toast('Simulated only. No actual email was sent.')});
 document.querySelectorAll('[data-email-fail]').forEach(b=>b.onclick=()=>{const e=state.outbox[b.dataset.emailFail];if(e.due>day)return;e.status='Failed';e.attempts=(e.attempts||0)+1;save();render()});
}

render();
